#include <cstdio>
#include <cstdlib>
#include <cstddef>

// sqrt(2/pi) for the tanh approximation of GELU.
inline constexpr float kGeluScalingFactor = 0.7978845608028654f;

class GeluKernel1;
class GeluKernel2;

