  q.parallel_for<GeluKernel1>(sycl::range<1>(n), [=](sycl::id<1> idx) {
     std::size_t i = idx[0];
     float xi = inp[i];
     float cube = 0.044715f * xi * xi * xi;
     out[i] = 0.5f * xi * (1.0f + sycl::tanh(kGeluScalingFactor * (xi + cube)));
   }).wait();
